   for(const g of e.groups){out+='<h4>'+esc(g.symbol+' · '+g.contracts.length+' / '+g.contracts.length+' recorded expiries')+'</h4>'+note('India VIX '+fmt(g.vix.previous)+' → '+fmt(g.vix.value)+' · '+(g.vix.delta===null?'change unavailable':g.vix.delta>0?'rising':g.vix.delta<0?'falling':'flat'))+table(['Expiry / strike / side','Break level ₹','Premium ₹ previous → event','Full PCR previous → event / Δ'],g.contracts.map((r:any)=>{const p=g.pcr.find((p:any)=>p.expiry===r.expiry);return [r.expiry+' / '+r.strike+' / '+g.side,fmt(r.event.level),fmt(r.event.previous)+' → '+fmt(r.event.value),fmt(p.previous,4)+' → '+fmt(p.value,4)+' / '+sign(p.delta,4)];}));}
   out+=note('Recorded premium agreement. '+e.scope+'. Not a buy/sell instruction.')+'</details>';
